body {
	--red: #a53740;
	--line: #e5dfda;
	--muted: #665f5b;
	width: calc(100% - 32px);
	max-width: 760px;
	background: #f7f5f2;
	color: #312d2b;
	font-weight: 400;
}
.todoapp {
	margin: 134px 0 0;
	border: 1px solid var(--line);
	border-radius: 14px;
	box-shadow: 0 4px 18px rgba(59,39,26,.06);
}
.todoapp h1 {
	top: auto;
	bottom: 100%;
	margin: 0 0 18px;
	font-size: 68px;
	line-height: 1;
	letter-spacing: -.045em;
}
.composer { display: flex; align-items: center; gap: 10px; padding: 18px; }
.new-todo, .todo-list li.editing .edit {
	min-width: 0;
	height: 48px;
	margin: 0;
	padding: 10px 14px;
	border: 1px solid #c9c1bb;
	border-radius: 7px;
	background: #fff;
	box-shadow: none;
	font-size: 18px;
}
.todoapp .new-todo::placeholder { font-style: normal; color: #746c66; }
button, .toggle-all-label, .toggle { cursor: pointer; }
.composer button {
	min-height: 48px;
	padding: 0 21px;
	border-radius: 7px;
	background: var(--red);
	color: white;
	font-size: 16px;
	font-weight: 600;
}
.composer button:hover { background: #882c34; }
.toggle-all-container { position: relative; background: #faf8f6; padding: 0 14px; border-bottom: 1px solid var(--line); }
.toggle-all { inset: 50% auto auto 16px; }
.toggle-all + label { position: static; width: fit-content; height: 44px; gap: 9px; color: var(--muted); font-size: 14px; }
.toggle-all + label:before { content: '✓'; padding: 0; transform: none; color: var(--muted); font-size: 17px; }
.todo-list li .view { display: grid; grid-template-columns: 44px minmax(0,1fr) 44px 44px; align-items: center; padding: 3px 10px; }
.todo-list li label { padding: 12px 8px; font-size: 18px; line-height: 1.45; word-break: normal; overflow-wrap: anywhere; color: #312d2b; }
.todo-list li .toggle + label, .todo-list li .toggle:checked + label { background-image: none; }
.todo-list li .toggle { position: relative; width: 44px; height: 44px; opacity: 1; }
.todo-list li .toggle:before { content: ''; display: grid; place-items: center; box-sizing: border-box; width: 24px; height: 24px; margin: auto; border: 2px solid #9a928c; border-radius: 50%; background: white; }
.todo-list li .toggle:checked:before { content: '✓'; color: white; background: #387769; border-color: #387769; font: bold 16px/1 Arial,sans-serif; }
.todo-list li.completed { background: #fafaf8; }
.todo-list li.completed label { color: #676e68; }
.todo-list li .destroy, .edit-task { display: grid; place-items: center; position: static; width: 44px; height: 44px; margin: 0; border-radius: 6px; color: var(--muted); }
.edit-task { font-size: 14px; }
.todo-list li:hover .destroy { display: grid; }
.todo-list li .destroy:after { height: auto; font-size: 24px; }
.edit-task:hover, .todo-list li .destroy:hover { background: #f6ecea; color: var(--red); }
.todo-list li.editing { padding: 6px 14px; }
.todo-list li.editing .edit { width: 100%; }
.todo-list:empty:after { display: block; padding: 24px 18px; content: 'No tasks in this view.'; color: var(--muted); }
.footer { grid-template-columns: 1fr auto 1fr; align-items: center; gap: 8px; height: auto; padding: 10px 16px; font-size: 14px; }
.footer:before { content: none; }
.todo-count { color: var(--muted); }
.todo-count strong { color: #312d2b; font-weight: 700; }
.filters { position: static; display: flex; padding: 2px; background: #f4f1ee; border-radius: 8px; }
.filters li { flex: 1; }
.filters li a { display: grid; place-items: center; box-sizing: border-box; min-height: 44px; margin: 0; padding: 0 12px; border-radius: 6px; }
.filters li a.selected { background: var(--red); color: white; border-color: var(--red); }
.clear-completed { justify-self: end; min-height: 44px; color: var(--red); }
.info { margin: 24px auto; color: var(--muted); font-size: 12px; }
.info p { display: inline-block; margin: 3px 5px; line-height: 1.5; }
.info p:first-child { display: block; }
:focus-visible, .toggle-all:focus-visible + label { outline: 2px solid var(--red); outline-offset: 1px; }
@media (max-width: 640px) {
	.todoapp { margin-top: 90px; }
	.todoapp h1 { font-size: 52px; margin-bottom: 12px; }
	.composer { padding: 12px; gap: 8px; }
	.todo-list li .view { padding: 2px 4px; }
	.todo-list li label { font-size: 16px; padding: 10px 4px; }
	.footer { grid-template-columns: 1fr auto; padding: 6px 12px 12px; gap: 2px; }
	.filters { grid-column: 1 / -1; grid-row: 2; }
}
